      buildSubBoxes(tree.getMinY(), tree.getMaxY(), tree.getMinX(), tree.getMaxX(), boxToRelation);
  return new Component2DPredicate(
      subBoxes.latShift,
      subBoxes.lonShift,
      subBoxes.latBase,
      subBoxes.lonBase,
      subBoxes.maxLatDelta,
      subBoxes.maxLonDelta,
      subBoxes.relations,
