    double shapeMinLat,
    double shapeMaxLat,
    double shapeMinLon,
    double shapeMaxLon,
    Function<Rectangle, Relation> boxToRelation) {
  final int minLat = encodedMinLatitude(shapeMinLat);
  final int maxLat = encodedMaxLatitude(shapeMaxLat);
  final int minLon = encodedMinLongitude(shapeMinLon);
  final int maxLon = encodedMaxLongitude(shapeMaxLon);

  if (shapeCannotMatchQuantizedPoints(minLat, maxLat, minLon, maxLon, shapeMinLon, shapeMaxLon)) {
    return emptyGrid();
