public Grid emptyGrid() {
  if (this.minGridShift < 1 || this.gridArity < 1) {
    throw new IllegalStateException("empty grid requires a positive shift");
  }
  return new Grid(this.minGridShift, this.minGridShift, 0, 0, 0, 0, new byte[0]);
