  double v1 = (bx - ax) * (cy - ay);
  double v2 = (cx - ax) * (by - ay);
  if (v1 > v2) {
    return this.counterClockwiseSign;
  } else if (v1 < v2) {
    return this.clockwiseSign;
  } else {
    return this.windingCollinear;
  }
}

